  'print-report':async d=>{const r=await api(`/research/${d.id}`);const frame=document.createElement('iframe');frame.style.cssText='position:fixed;width:0;height:0;bottom:0;border:0';document.body.append(frame);const doc=frame.contentDocument;doc.open();doc.write(`<!doctype html><html><head><title>${esc(r.topic)}</title><style>body{font-family:Arial,"Microsoft YaHei";padding:40px;line-height:1.8}table{border-collapse:collapse}td,th{border:1px solid #ddd;padding:8px}a{color:#444}</style></head><body>${md(r.report_md)}</body></html>`);doc.close();frame.contentWindow.focus();frame.contentWindow.print();setTimeout(()=>frame.remove(),1000);},
  'edit-skill':d=>editSkill(d.id), 'save-skill':async()=>{await api('/skills',{name:$('#skill-name').value.trim(),body:$('#skill-body').value.trim(),trigger_hint:$('#skill-trigger').value,style_notes:$('#skill-style').value});close();await skills();},
